  input  wire                                  i_hw_we_sha_irq_raw_tmo,
  output logic                                 o_sha_irq_raw_ent,
  input  wire                                  i_hw_wdata_sha_irq_raw_ent,
  input  wire                                  i_hw_we_sha_irq_raw_ent,
  output logic                                 o_sha_irq_raw_flt,
  input  wire                                  i_hw_wdata_sha_irq_raw_flt,
