  logic [4:0] reg_sha_ctrl_ctxsel;
  logic [4:0] w_sha_ctrl_ctxsel_nxt;
  logic [3:0] reg_sha_ctrl_algo;
  logic [3:0] w_sha_ctrl_algo_nxt;
  logic reg_sha_ctrl_en;
  logic w_sha_ctrl_en_nxt;
  logic [LPARA_DATA_W-1:0] w_sha_ctrl_value;
  logic w_we_sha_cmd;
  logic reg_sha_cmd_seed;
