  logic [PARA_SHA_SEED_COUNT-1:0][31:0] reg_sha_seed_wd;
  logic [PARA_SHA_SEED_COUNT-1:0][31:0] w_sha_seed_wd_nxt;
  logic [PARA_SHA_SEED_COUNT-1:0] w_we_sha_seed;
