  logic w_sha_irq_en_udf_nxt;
  logic reg_sha_irq_en_ovf;
  logic w_sha_irq_en_ovf_nxt;
  logic [15:0] reg_sha_irq_en_cdone;
  logic [15:0] w_sha_irq_en_cdone_nxt;
  logic [LPARA_DATA_W-1:0] w_sha_irq_en_value;
  logic w_we_sha_irq_inj;
  logic reg_sha_irq_inj_len;
  logic w_sha_irq_inj_len_nxt;
  logic reg_sha_irq_inj_tmo;
  logic w_sha_irq_inj_tmo_nxt;
  logic reg_sha_irq_inj_ent;
  logic w_sha_irq_inj_ent_nxt;
