  logic w_sha_irq_inj_flt_nxt;
  logic reg_sha_irq_inj_cfg;
  logic w_sha_irq_inj_cfg_nxt;
  logic reg_sha_irq_inj_axi;
  logic w_sha_irq_inj_axi_nxt;
  logic reg_sha_irq_inj_udf;
  logic w_sha_irq_inj_udf_nxt;
  logic reg_sha_irq_inj_ovf;
  logic w_sha_irq_inj_ovf_nxt;
  logic [15:0] reg_sha_irq_inj_cdone;
  logic [15:0] w_sha_irq_inj_cdone_nxt;
