        if ((PARA_SHA_SEED_COUNT > 32'd4) && (PARA_SHA_SEED_COUNT <= LPARA_SHA_SEED_MAX_COUNT))
          w_rdata_nxt = w_sha_seed_value[4];
      end
      (LPARA_SHA_SEED_BASE_OFFSET + (32'd5 * LPARA_SHA_SEED_OFFSET_STRIDE)): begin
        if ((PARA_SHA_SEED_COUNT > 32'd5) && (PARA_SHA_SEED_COUNT <= LPARA_SHA_SEED_MAX_COUNT))
          w_rdata_nxt = w_sha_seed_value[5];
