        if ((PARA_SHA_SEED_COUNT > 32'd6) && (PARA_SHA_SEED_COUNT <= LPARA_SHA_SEED_MAX_COUNT))
          w_rdata_nxt = w_sha_seed_value[6];
      end
      (LPARA_SHA_SEED_BASE_OFFSET + (32'd7 * LPARA_SHA_SEED_OFFSET_STRIDE)): begin
        if ((PARA_SHA_SEED_COUNT > 32'd7) && (PARA_SHA_SEED_COUNT <= LPARA_SHA_SEED_MAX_COUNT))
          w_rdata_nxt = w_sha_seed_value[7];
      end
      (LPARA_SHA_SEED_BASE_OFFSET + (32'd8 * LPARA_SHA_SEED_OFFSET_STRIDE)): begin
        if ((PARA_SHA_SEED_COUNT > 32'd8) && (PARA_SHA_SEED_COUNT <= LPARA_SHA_SEED_MAX_COUNT))
          w_rdata_nxt = w_sha_seed_value[8];
      end
      (LPARA_SHA_SEED_BASE_OFFSET + (32'd9 * LPARA_SHA_SEED_OFFSET_STRIDE)): begin
        if ((PARA_SHA_SEED_COUNT > 32'd9) && (PARA_SHA_SEED_COUNT <= LPARA_SHA_SEED_MAX_COUNT))
          w_rdata_nxt = w_sha_seed_value[9];
      end
      (LPARA_SHA_SEED_BASE_OFFSET + (32'd10 * LPARA_SHA_SEED_OFFSET_STRIDE)): begin
        if ((PARA_SHA_SEED_COUNT > 32'd10) && (PARA_SHA_SEED_COUNT <= LPARA_SHA_SEED_MAX_COUNT))
          w_rdata_nxt = w_sha_seed_value[10];
      end
      (LPARA_SHA_SEED_BASE_OFFSET + (32'd11 * LPARA_SHA_SEED_OFFSET_STRIDE)): begin
