          w_rdata_nxt = w_sha_seed_value[15];
      end
      LPARA_SHA_STS_OFFSET: w_rdata_nxt = w_sha_sts_value;
      LPARA_SHA_LVL_OFFSET: w_rdata_nxt = w_sha_lvl_value;
      LPARA_SHA_BLK_OFFSET: w_rdata_nxt = w_sha_blk_value;
